diff --git a/solution.mjs b/solution.mjs
new file mode 100644
index 0000000..ab09877
--- /dev/null
+++ b/solution.mjs
@@ -0,0 +1,11 @@
+export function flatten(arr, depth = 1) {
+  let result = [];
+  for (const item of arr) {
+    if (Array.isArray(item)) {
+      result = result.concat(flatten(item, depth - 1));
+    } else {
+      result.push(item);
+    }
+  }
+  return result;
+}
